-- Resets the vihkotappelu game data (VihkotappeluUnits, VihkotappeluFactions,
-- VihkotappeluSprites and their translation/link tables) to the canonical
-- seed: the faction units of the two factions Dalmen and Zhaglon with English
-- ('en') and Finnish ('fi') names, and the 16x16 pixel-art sprites as JSON
-- per-pixel color grids (null = transparent, '#rrggbb'/'#rrggbbaa', or 'side'
-- = the owning side's faction color). This file IS the seed — the
-- vihkotappelu repo holds no data files; the game server reads this data via
-- GET /vihkotappelu/data. Sprite rows are edited here directly or pushed via
-- the bulk PUT payload (fetch-data / sync-data in the vihkotappelu repo).
-- Run via: just reset-vihkotappelu   (from the klapi repo root)
-- Or manually: sqlite3 api/Database/klapi.db < api/Database/reset-vihkotappelu.sql

PRAGMA foreign_keys = ON;

BEGIN TRANSACTION;

DELETE FROM VihkotappeluFactionUnits;
DELETE FROM VihkotappeluFactionTranslations;
DELETE FROM VihkotappeluFactions;
DELETE FROM VihkotappeluUnitTranslations;
DELETE FROM VihkotappeluUnits;
DELETE FROM VihkotappeluSprites;








COMMIT;
